probes.c1:
from grades import grade
want = {0: "F", 30: "F", 49: "F", 50: "D", 57: "D", 64: "D", 65: "C", 72: "C", 79: "C",
        80: "B", 85: "B", 89: "B", 90: "A", 95: "A", 100: "A"}
for s, g in want.items():
    try:
        got = grade(s)
    except Exception as e:
        raise AssertionError((s, repr(e)))
    assert got == g, (s, got, g)

probes.c2:
from grades import grade
for s in (-1, -50, 101, 1000):
    try:
        got = grade(s)
    except ValueError:
        continue
    raise AssertionError(("no ValueError", s, got))
for s in (0, 100):
    try:
        grade(s)
    except Exception as e:
        raise AssertionError((s, repr(e)))

